const annee = ["premiere", "deuxieme", "troisieme"];

export default function Filliere() {
  return (
    <>
    <div className="nav-bar"></div>
      <div className='d-flex flex-column justify-content-center'>
        {annee.map((e) => (<button key={e}>{e} annee</button>))}
      </div>
    </>
  );
}
